cards.solution:
const kalkulator = {
  nilai: 0,
  tambah(n) {
    kalkulator.nilai += n;
  },
};
kalkulator.tambah(5);
kalkulator.tambah(3);
console.log(`Nilai: ${kalkulator.nilai}`);
